/// <summary>
/// Vendor rebate request class
/// </summary>
[DataContractAttribute]
public final class METVendorRebateRequest
{
    DataAreaId dataAreaId;
    METVendorRebateDealContract metVendorRebateDealContract;

}

Method.Source:
/// <summary>
/// Data area Id 
/// </summary>
/// <param name = "_dataAreaId"></param>
/// <returns></returns>
[DataMember(extendedTypeStr(dataAreaId))]
public str parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    if (!prmIsDefault(_dataAreaId))
    {
        dataAreaId = _dataAreaId;
    }
    return dataAreaId;
}

/// <summary>
/// Vendor rebate contract class
/// </summary>
/// <param name = "_metVendorRebateDealContract"></param>
/// <returns></returns>
[DataMember(identifierStr(METVendorRebateDealContract))]
public METVendorRebateDealContract parmVendorRebateDealContract(METVendorRebateDealContract _metVendorRebateDealContract = metVendorRebateDealContract)
{
    if (!prmIsDefault(_metVendorRebateDealContract))
    {
        metVendorRebateDealContract = _metVendorRebateDealContract;
    }
    return metVendorRebateDealContract;
}
